    userName: context.userName,
    language: context.language || interfaceLanguage,
    messageId: undefined,
    messageIndex: undefined,
    messageContent: '',
    chatMessages: [],
    persistedStorage,
    firstMes: context.firstMes,
    alternateGreetings: context.alternateGreetings,
    characterExtensions: context.characterExtensions,
