    // 插件换文档等场景），这条唯一的补投会被静默丢弃 ⇒ 帧内永远停在 boot 快照上。
    // 旧行为靠 srcdoc 内联全量数据兜底，所以问题不显；[P0-SRCDOC-SLIM] 把
    // characterExtensions / chatMessages 移出 boot 后，这里就是数据到达的唯一通道。
    lastPostedContextSignatureRef.current = '';
    postLiveContext();
