    const frameDoc = frame?.contentDocument;
    if (!frameDoc || frameDoc === document || prefersImmersive) return;
    if (contrastEnhancerRef.current) {
      contrastEnhancerRef.current.dispose();
      contrastEnhancerRef.current = null;
    }
    const container = frameDoc.body || (frameDoc.documentElement as HTMLElement | null);
    if (!container) return;
